#include "navcore/route_monitor.hpp"
#include "navcore/road_event.hpp"
namespace navcore { RouteMonitor::RouteMonitor(MonitorConfig c):c_(c){} RouteState RouteMonitor::update(const MatchResult&m,const RouteResult&r){bool on=m.lateral_distance_m<=c_.lateral_threshold_m;for(const auto&e:r.path_edges)if(edge_key(e)==edge_key(m.matched_edge))on=true;if(on){misses_=0;return RouteState::ON_ROUTE;}++misses_;return misses_>=c_.debounce_samples?RouteState::DEVIATED:RouteState::POSSIBLE_DEVIATION;} RerouteResult reroute_if_needed(const RoadGraph&g,const MatchResult&m,const RouteResult&old,const std::string&dest,RouteState st,const RoadEventOverlay&ev,RouteOptions o){RerouteResult x;x.previous_route=old;bool ahead=false;for(const auto&e:old.path_edges)if(ev.closed(e)){ahead=true;break;}if(st!=RouteState::DEVIATED&&!ahead)return x;x.reason=ahead?"closure_ahead":"sustained_deviation";ev.apply(o);auto t=std::chrono::steady_clock::now();x.new_route=route(g,m.matched_edge.to,dest,o);x.latency_ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count();x.rerouted=true;return x;} }